-- Explicit corrections to two retained authored records, not new quests.
local _,ns=...
local revisions={{["originalOpening"]="Kobold workers had made camp near the Echo Ridge Mine, a larger infestation than Marshal McBride’s scouts had expected.",["questID"]=15,["row"]={["atomIDs"]={"15:description:1-80","15:description:83-157"},["bridge"]="The scouts found the infestation larger than expected. Kobold workers had made camp around Echo Ridge Mine, where the trouble reached beyond the woods north of the abbey.",["bridgeFrom"]=7,["bridgeReplacesSetup"]=true,["opening"]="Kobold workers had made camp near the Echo Ridge Mine, a larger infestation than Marshal McBride’s scouts had expected.",["pending"]="{actor} would confront the workers camped near Echo Ridge.",["result"]="{actor} brought back word of the workers gathered near Echo Ridge.",["review"]="SOURCE_BOUND_WHOLE_MANUSCRIPT_CORRECTION",["sourceHash"]="1df8e6166fda022ef00b9cc823dc4a47d3f72f71d24024dc63e1760ab411f3d7"}},{["originalOpening"]="The kobolds’ foothold in the mine threatened to grow stronger the longer they remained. Marshal McBride wanted them cleared from Northshire.",["questID"]=21,["row"]={["aftermath"]="Others would be sent against any kobolds still in the mine; the marshal had further duties in mind.",["atomIDs"]={"21:description:1-78","21:description:81-128","21:description:153-254"},["bridge"]="The kobolds' foothold at Echo Ridge grew more dangerous the longer it lasted. McBride wanted the laborers driven from the mine before they could settle deeper into Northshire.",["bridgeFrom"]=15,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"21:completion:1-80","21:completion:82-158","21:completion:160-189"},["opening"]="The kobolds’ foothold in the mine threatened to grow stronger the longer they remained. Marshal McBride wanted them cleared from Northshire.",["pending"]="{actor} would confront the kobold laborers in Echo Ridge Mine.",["result"]="The marshal commended {actor}'s help against the mine's laborers.",["review"]="SOURCE_BOUND_WHOLE_MANUSCRIPT_CORRECTION",["sourceHash"]="3cdd14a1eb633382f6c90249a3dba2c08de418e6722e17b41f0b7ce4a9ffdd84"}},{["originalOpening"]="Gar’Thok regarded the Razormane’s fortified camps as an unfinished struggle for Durotar. Their remaining footholds west of Razor Hill were the targets he wanted struck.",["questID"]=837,["row"]={["atomIDs"]={"837:description:1-101","837:description:103-227","837:description:232-267","837:description:269-344","837:description:346-390","837:description:392-436","837:description:438-510"},["editorialVersion"]="overnight-horde-1",["independentReview"]="PENDING",["opening"]="The Razormane had held much of Durotar before the Horde arrived. Gar'Thok wanted the fortified camps west of Razor Hill broken up, to secure the borders of the orcs' new homeland.",["pending"]="{actor} would confront the Razormane in their fortified camps.",["result"]="Gar'Thok credited {actor} with bringing Durotar's borders closer to safety.",["review"]="SOURCE_BOUND_WHOLE_MANUSCRIPT_CORRECTION",["sourceHash"]="6487b98bfdd978aea76502280a12c4958f36e484ce6c027240651bc8eb867bf2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}}}
for _,revision in ipairs(revisions) do
 local old=assert(ns.AthenaQuestContextData[revision.questID],"Missing retained editorial")
 assert(old.sourceHash==revision.row.sourceHash and old.opening==revision.originalOpening,"Retained editorial changed; re-review correction")
